// v23.xx (gfx34), HIS ORDER 2026-10-12 (the graphics program, item 9, atmosphere; his answer 20, gritty and grounded): DUST HANGS IN
// THE LAMP LIGHT. At night (and in the lamp hours of a dawn or a dusk) every lamp in view now has a handful of dust motes drifting
// slowly through its pool, catching the light in the lamp colour: about five a lamp, more in fog. Where each mote is, how bright it
// twinkles and how it drifts is a pure function of the raid clock and the lamp and mote numbers, so there is no random draw and
// nothing to store; a lamp that flickers dims its motes with it and a blackout or a lamp the weather has put out has none. Drawn after
// the light and before the fog of war sheet (gfxPreFogE), so they glow and stay under the fog. Effects LOW draws three a lamp.
function gfxMoteSpr(){
  var st=gfxStore('gfxE'), m=st.m, c, x, gr;
  if(m.mote) return m.mote;
  c=document.createElement('canvas'); c.width=c.height=16; x=c.getContext('2d');
  gr=x.createRadialGradient(8,8,0,8,8,8);
  gr.addColorStop(0,'rgba(255,248,226,1)'); gr.addColorStop(0.4,'rgba(255,236,196,.55)'); gr.addColorStop(1,'rgba(255,220,170,0)');
  x.fillStyle=gr; x.fillRect(0,0,16,16); m.mote=c;
  return c;
}
function gfxMoteDraw(){
  var m=GFXE.wm, LS=G.lights, i, j, L, nm, fk, dk, t=G.t||0, n=0, Z=ZOOM(), spr, mx, my, h, a, sz, ph, fg;
  if(!m||!LS||!LS.length) return 0;
  dk=isDay()?((tod()&&tod().lights)||0):1;
  if(dk<0.2) return 0;
  fg=(wx()&&wx().fog)||0;
  nm=(CFG.fxLevel===0)?3:(5+Math.round(3*Math.min(1,fg)));
  var vx0=VX-60, vy0=VY-60, vx1=VX+W/Z+60, vy1=VY+H/Z+60;
  for(i=0;i<LS.length;i++){
    L=LS[i];
    if(L.x<vx0||L.x>vx1||L.y<vy0||L.y>vy1) continue;
    fk=(L.fl?(0.72+0.28*Math.sin(t*11+L.f)):1)*wx().lights*(isDay()?tod().lights:1);
    if(fk<=0.05) continue;
    if(!n){ spr=gfxMoteSpr(); wc.save(); wc.setTransform(m.a,m.b,m.c,m.d,m.e,m.f); wc.globalCompositeOperation='lighter'; }
    for(j=0;j<nm;j++){
      ph=i*1.7+j*2.39;
      mx=L.x+Math.sin(t*0.21*(1+j*0.13)+ph)*L.r*0.42+Math.sin(t*0.07+j)*8;
      my=L.y+Math.sin(t*0.17*(1+j*0.11)+ph*1.3)*L.r*0.26;
      h=10+28*(0.5+0.5*Math.sin(t*0.29+ph*0.7));
      a=(0.22+0.3*(0.5+0.5*Math.sin(t*(1.1+j*0.23)+ph*3.1)))*Math.min(1,fk)*Math.min(1,dk*1.4)*(L.i>0?Math.min(1.2,L.i*2.2):1);
      sz=2.2+1.6*(0.5+0.5*Math.sin(ph*5.3));
      wc.globalAlpha=Math.max(0,Math.min(1,a));
      wc.drawImage(spr,mx-sz,my-h-sz,sz*2,sz*2);
      n++;
    }
  }
  if(n) wc.restore();
  return n;
}
// ===== GFX-E end =====

