 run:function(){
   var bad=[], g=null, p, i, L=null, n, spr, cond0=P.cond, tod0=null, td;
   var cnt=function(img){ var q=0, orig=wc.drawImage; wc.drawImage=function(im){ if(im===img) q++; return orig.apply(wc,arguments); }; try{ __frame(0.016); } finally { delete wc.drawImage; } return q; };
   try{
     if(!(window.__gfxStage&&window.__frame&&window.__state&&window.__endRaid)) return 'SKIP: this fixture has no gfx stage';
     g=__gfxStage({frames:2,cond:'night'});
     if(!g) return 'SKIP: __gfxStage built no raid';
     if(g.sim) return 'SKIP: the staged raid is a sim raid';
     if(typeof gfxMoteSpr!=='function') return 'no lamp dust: no gfxMoteSpr';
     GFX.bypass=0; G.shake=0; p=g.player; tod0=g.tod;
     for(i=0;i<(G.lights||[]).length;i++){ if(!G.lights[i].fl){ L=G.lights[i]; break; } }
     if(!L) return 'SKIP: no steady lamp on this map';
     if(!(wx().lights>0.3)) return 'SKIP: the staged weather puts the lamps out';
     p.x=L.x+20; p.y=L.y+30; p.vx=0; p.vy=0; G.anchX=undefined;
     __frame(0.016);
     spr=gfxMoteSpr();
     n=cnt(spr); if(n<5) bad.push('a lit lamp at night drew '+n+' dust motes');
     P.cond='day'; for(i=0;i<TODS.length;i++) if(TODS[i].id==='noon') g.tod=TODS[i];
     n=cnt(spr); if(n!==0) bad.push('noon drew '+n+' dust motes');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{
     P.cond=cond0; try{ if(g&&tod0) g.tod=tod0; }catch(_td){}
     keys={};
     try{ var g2=__state(); if(g2&&!g2.over&&!g2.sim) __endRaid('abandon'); }catch(_e){}
     __topClear();
   }
   return bad.length?bad.join('; '):null; }},
